import json, sys
from collections import deque


def solve(request):
    mem0 = tuple(request['memory'])
    threads = [tuple(tuple(i) for i in t) for t in request['threads']]
    T = len(threads)
    lens = tuple(len(t) for t in threads)

    start = (
        tuple([0] * T),          # pcs
        tuple([()] * T),        # buffers (FIFO of (addr,width,value))
        mem0,                   # shared memory
        tuple([()] * T, ),      # observations per thread
    )
    seen = {start}
    q = deque([start])
    outcomes = set()

    while q:
        pcs, bufs, mem, obs = q.popleft()

        # terminal: all threads finished and every buffer empty
        if all(pcs[t] == lens[t] for t in range(T)) and all(not b for b in bufs):
            outcomes.add((obs, mem))
            continue

        for t in range(T):
            # ---- 1. execute next instruction of thread t ----
            if pcs[t] < lens[t]:
                ins = threads[t][pcs[t]]
                op = ins[0]
                npcs = pcs[:t] + (pcs[t] + 1,) + pcs[t + 1:]
                nbufs = bufs
                nmem = mem
                nobs = obs
                ok = True
                if op == 'store':
                    _, a, w, v = ins
                    nbufs = bufs[:t] + (bufs[t] + ((a, w, v),),) + bufs[t + 1:]
                elif op == 'load':
                    _, a, w = ins
                    val = 0
                    for i in range(w):
                        off = a + i
                        b = None
                        for (sa, sw, sv) in reversed(bufs[t]):
                            if sa <= off < sa + sw:
                                b = (sv >> (8 * (off - sa))) & 0xFF
                                break
                        if b is None:
                            b = mem[off]
                        val |= b << (8 * i)
                    nobs = obs[:t] + (obs[t] + (val,),) + obs[t + 1:]
                elif op == 'fence':
                    if bufs[t]:
                        ok = False
                elif op == 'xchg':
                    _, a, w, v = ins
                    if bufs[t]:
                        ok = False
                    else:
                        old = 0
                        for i in range(w):
                            old |= mem[a + i] << (8 * i)
                        newbytes = tuple((v >> (8 * i)) & 0xFF for i in range(w))
                        nmem = mem[:a] + newbytes + mem[a + w:]
                        nobs = obs[:t] + (obs[t] + (old,),) + obs[t + 1:]
                else:
                    ok = False
                if ok:
                    st = (npcs, nbufs, nmem, nobs)
                    if st not in seen:
                        seen.add(st)
                        q.append(st)

            # ---- 2. drain oldest store of thread t ----
            if bufs[t]:
                a, w, v = bufs[t][0]
                newbytes = tuple((v >> (8 * i)) & 0xFF for i in range(w))
                nmem = mem[:a] + newbytes + mem[a + w:]
                nbufs = bufs[:t] + (bufs[t][1:],) + bufs[t + 1:]
                st = (pcs, nbufs, nmem, obs)
                if st not in seen:
                    seen.add(st)
                    q.append(st)

    return {
        "outcomes": [
            {"reads": [list(r) for r in obs], "memory": list(mem)}
            for obs, mem in outcomes
        ]
    }


if __name__ == '__main__':
    out = []
    for line in sys.stdin:
        if not line.strip():
            continue
        out.append(json.dumps(solve(json.loads(line))))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))
